// CC-RUSSIAN-STRESS Phase 3 — the ingest is the only write path, and the
// audit claim belongs to a human.
//
// Two things can go wrong that a unit test cannot see, because both are edits
// to the very files the tests read:
//
//   L1  Someone hand-edits src/ru_stress_data.rs. It is generated; a hand edit
//       is silently erased by the next ingest run, so a "fix" applied there
//       looks like it worked and then vanishes. Same law as word_data.rs,
//       pinyin_inventory.rs and stroke_counts.rs.
//
//   L2  Someone flips AUDITED in the generated file instead of in
//       config/ru-stress-audit.json. THIS IS THE ONE THAT MATTERS. The dark
//       rule is the only thing standing between 973 rows of Wiktionary
//       pre-fill and a child being taught the wrong stress. The claim is a
//       human act recorded in the config; the table merely copies it. If the
//       two disagree, the copy is a forgery -- and a unit test cannot catch it,
//       because the unit test reads the forged constant and happily agrees
//       with itself.
import fs from "node:fs";
import path from "node:path";

const ROOT = path.dirname(new URL(import.meta.url).pathname) + "/..";
const SELFTEST = process.argv.includes("--selftest");

function evaluate(rs, claimRaw) {
  const fails = [];
  if (!/GENERATED by tools\/ru_stress_ingest\.py/.test(rs))
    fails.push("src/ru_stress_data.rs lost its GENERATED header — it is written by tools/ru_stress_ingest.py and a hand edit will be erased by the next run");

  const m = /pub const AUDITED: bool = (true|false);/.exec(rs);
  if (!m) {
    fails.push("src/ru_stress_data.rs has no AUDITED constant — the dark rule has no switch, so unaudited stress marks could reach a player");
    return fails;
  }
  const inTable = m[1] === "true";
  let claim;
  try { claim = JSON.parse(claimRaw); }
  catch { fails.push("config/ru-stress-audit.json is not valid JSON — the audit claim is unreadable"); return fails; }
  const inClaim = claim.audited === true;

  if (inTable !== inClaim)
    fails.push(
      `AUDITED is ${inTable} in the generated table but ${inClaim} in config/ru-stress-audit.json. ` +
      `The claim is a HUMAN act and lives in the config; the table only copies it. ` +
      (inTable
        ? "Flipping it in the generated file forges the audit — 973 rows of Wiktionary pre-fill would go live unread."
        : "Re-run tools/ru_stress_ingest.py so the table picks up the signed claim.")
    );
  if (inClaim && !claim.by)
    fails.push("config/ru-stress-audit.json claims audited=true with no `by` — an audit is signed by a person, or it is not an audit");
  return fails;
}

if (SELFTEST) {
  const good = 'GENERATED by tools/ru_stress_ingest.py\npub const AUDITED: bool = false;\n';
  const lesions = [
    ["AUDITED forged true in the generated table", good.replace("false", "true"), '{"audited":false}'],
    ["config signed but the table never regenerated", good, '{"audited":true,"by":"Eric"}'],
    ["audited=true with nobody signing it", good.replace("false", "true"), '{"audited":true,"by":null}'],
    ["the GENERATED header stripped", 'pub const AUDITED: bool = false;\n', '{"audited":false}'],
    ["the AUDITED switch deleted outright", 'GENERATED by tools/ru_stress_ingest.py\n', '{"audited":false}'],
  ];
  let bad = 0;
  for (const [name, rs, claim] of lesions)
    if (evaluate(rs, claim).length === 0) { console.error(`  SURVIVED: ${name}`); bad++; }
  if (evaluate(good, '{"audited":false}').length !== 0) { console.error("  FALSE POSITIVE on the clean pair"); bad++; }
  if (bad) { console.error(`ru-stress-ingest-check: FAILED\n  ${bad} lesion(s) not caught`); process.exit(1); }
  console.log(`ru-stress-ingest-check: selftest OK — all ${lesions.length} lesions fail the build`);
  process.exit(0);
}

const fails = evaluate(
  fs.readFileSync(path.join(ROOT, "src/ru_stress_data.rs"), "utf8"),
  fs.readFileSync(path.join(ROOT, "config/ru-stress-audit.json"), "utf8"),
);
if (fails.length) {
  console.error("ru-stress-ingest-check: FAILED");
  for (const f of fails) console.error("  " + f);
  process.exit(1);
}
console.log("ru-stress-ingest-check: OK — generated table intact, audit claim matches the human-signed config");
